INSERT INTO [dbo].[metaViews] ([ViewId], [Name], [IsRelatedView], [CheckCode], [CheckCodeBefore], [CheckCodeAfter], [RecordCheckCodeBefore], [RecordCheckCodeAfter], [CheckCodeVariableDefinitions], [Width], [Height], [Orientation], [LabelAlign], [EIWSOrganizationKey], [EIWSFormId], [EWEOrganizationKey], [EWEFormId]) VALUES
(1, N'CaseReport', 0, N'/*
	1. use the "find code block" to navigate and create code blocks.
	2. all check code needs to appear inside of checkcode blocks.
	
*/
Field Sex
	After
		//add code here
		IF Sex = "1" THEN
			ENABLE Pregnant
		ELSE
			DISABLE Pregnant
			CLEAR Pregnant
		END-IF
	End-After
End-Field

Field LastName
	Before
		//add code here
		IF Sex = "1" THEN
			ENABLE Pregnant
		ELSE
			DISABLE Pregnant
			CLEAR Pregnant
		END-IF
	End-Before
End-Field
', N'', N'', N'', N'', N'', 768, 993, N'Portrait', N'Horizontal', N'', N'', N'', N''),
(2, N'FoodHistory', 0, N'Field DOB
	After
		// Assigns the difference in years between the value entered into DOB and the value
		// entered into DateOfInterview to the AGE field. This acts as an automatic age
		// calculator during data entry.
		ASSIGN AGE = YEARS(DOB, DateofInterview)
	End-After
End-Field

Field GetCoordinates
	Click
		GEOCODE PatientAddress, Latitude, Longitude
	End-Click
End-Field

Field OnsetDate
	After
		ASSIGN OnsetWeek = EPIWEEK(OnsetDate)
	End-After
End-Field

Field Asian
	Click
		ASSIGN Black = (-)
		ASSIGN AmericanIndianAlaskanNative = (-)
		ASSIGN NativeHawaiianOtherPacificIslander = (-)
		ASSIGN White = (-)
		ASSIGN Multiracial = (-)
		ASSIGN UnknownOther = (-)
	End-Click
End-Field

Field Black
	Click
		ASSIGN Asian = (-)
		ASSIGN AmericanIndianAlaskanNative = (-)
		ASSIGN NativeHawaiianOtherPacificIslander = (-)
		ASSIGN White = (-)
		ASSIGN Multiracial = (-)
		ASSIGN UnknownOther = (-)
	End-Click
End-Field

Field Multiracial
	Click
		ASSIGN Asian = (-)
		ASSIGN AmericanIndianAlaskanNative = (-)
		ASSIGN NativeHawaiianOtherPacificIslander = (-)
		ASSIGN White = (-)
		ASSIGN Black = (-)
		ASSIGN UnknownOther = (-)
	End-Click
End-Field

Field NativeHawaiianOtherPacificIslander
	Click
		ASSIGN Asian = (-)
		ASSIGN AmericanIndianAlaskanNative = (-)
		ASSIGN Multiracial = (-)
		ASSIGN White = (-)
		ASSIGN Black = (-)
		ASSIGN UnknownOther = (-)
	End-Click
End-Field

Field UnknownOther
	Click
		ASSIGN Asian = (-)
		ASSIGN AmericanIndianAlaskanNative = (-)
		ASSIGN Multiracial = (-)
		ASSIGN White = (-)
		ASSIGN Black = (-)
		ASSIGN NativeHawaiianOtherPacificIslander = (-)
	End-Click
End-Field

Field AmericanIndianAlaskanNative
	Click
		ASSIGN Asian = (-)
		ASSIGN UnknownOther = (-)
		ASSIGN Multiracial = (-)
		ASSIGN White = (-)
		ASSIGN Black = (-)
		ASSIGN NativeHawaiianOtherPacificIslander = (-)
	End-Click
End-Field

Field White
	Click
		ASSIGN Asian = (-)
		ASSIGN UnknownOther = (-)
		ASSIGN Multiracial = (-)
		ASSIGN AmericanIndianAlaskanNative = (-)
		ASSIGN Black = (-)
		ASSIGN NativeHawaiianOtherPacificIslander = (-)
	End-Click
End-Field

Field FeverTemp
	After
		// if the fever temperature field has been filled in and the fever checkbox is unchecked,
		// prompt the user that there might be a problem.
		IF NOT FeverTemp = (.) AND Fever = (-) THEN
			DIALOG "Warning: A fever temperature has been entered, but ''fever'' was not selected as a symptom."
		END-IF
	End-After
End-Field
', N'', N'', N'', N'', N'', 768, 1028, N'Portrait', N'Vertical', N'', N'', N'', N'');
